import{_ as e,o as t,c as r,a2 as i}from"./chunks/framework.BZO4qERu.js";const g=JSON.parse('{"title":"Agents / ACP","description":"","frontmatter":{},"headers":[],"relativePath":"zh/getting-started/acp.md","filePath":"zh/getting-started/acp.md","lastUpdated":1780941437000}'),o={name:"zh/getting-started/acp.md"};function n(s,a,l,c,h,d){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="agents-acp" tabindex="-1">Agents / ACP <a class="header-anchor" href="#agents-acp" aria-label="Permalink to &quot;Agents / ACP&quot;">​</a></h1><p>Memoh 可以把机器人连接到 ACP 兼容的编码智能体。ACP 智能体是外部编码工作流，可以从机器人的聊天 workspace 里工作，同时把自己的会话和普通 chat / discuss 分开。</p><p>当前界面里可见的设置示例包括 Codex 和 Claude Code。它们是当前支持/展示的配置路径，不代表未来只能接这两种 ACP 兼容智能体。</p><hr><h2 id="设置流程" tabindex="-1">设置流程 <a class="header-anchor" href="#设置流程" aria-label="Permalink to &quot;设置流程&quot;">​</a></h2><ol><li>打开机器人 <strong>详情页</strong>。</li><li>进入 <strong>Agents</strong> tab。</li><li>启用要使用的智能体。</li><li>按该智能体展示的方式选择设置或授权模式，例如 OAuth、API Key、或自管理配置。</li><li>保存。</li><li>打开聊天 workspace，从那里启动已启用的智能体。</li></ol><p>不同智能体的字段会不一样，因为每个 ACP 集成都有自己的授权和设置要求。</p><hr><h2 id="acp-agent-会话" tabindex="-1">ACP Agent 会话 <a class="header-anchor" href="#acp-agent-会话" aria-label="Permalink to &quot;ACP Agent 会话&quot;">​</a></h2><p>ACP 工作使用 <code>acp_agent</code> 会话类型。这类会话由 Agents/ACP 工作流创建和管理。</p><p>它不会通过普通 <code>/new chat</code> 或 <code>/new discuss</code> 路由创建。网页端可以按 <code>acp_agent</code> 过滤会话，把编码智能体工作和日常对话分开看。</p><hr><h2 id="附件" tabindex="-1">附件 <a class="header-anchor" href="#附件" aria-label="Permalink to &quot;附件&quot;">​</a></h2><p>ACP Agent 会话目前不支持消息附件。需要直接给机器人发文件或图片时，请使用普通 chat 会话。</p><hr><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="/zh/getting-started/bot.html">机器人</a></li><li><a href="/zh/getting-started/sessions.html">会话</a></li><li><a href="/zh/getting-started/files.html">文件</a></li></ul>',17)])])}const A=e(o,[["render",n]]);export{g as __pageData,A as default};
